sp_ListarContasReceber	ONLY_FULL_GROUP_BY,STRICT_TRANS_TABLES,NO_ZERO_IN_DATE,NO_ZERO_DATE,ERROR_FOR_DIVISION_BY_ZERO,NO_ENGINE_SUBSTITUTION	CREATE DEFINER=`root`@`%` PROCEDURE `sp_ListarContasReceber`(IN p_idEmpresa INT)\nBEGIN\n\n    SELECT\n\n        cr.idContaReceber,\n\n        cr.idEmpresa,\n\n        cr.cliente_id,\n\n        cr.pedido_id,\n\n        cr.lancamento_id,\n\n        cr.descricao,\n\n        cr.valorTotal,\n\n        cr.valorPago,\n\n        cr.dthVencimento,\n\n        cr.dthPagamento,\n\n        cr.dthCriacao,\n\n        cr.status,\n\n        c.Nome AS nomeCliente,\n\n        c.CNPJ_CPF AS cpfCNPJ,\n\n        CASE\n\n            WHEN cr.valorPago >= cr.valorTotal THEN 'PAGO'\n\n            WHEN cr.dthVencimento < CURDATE() AND cr.valorPago < cr.valorTotal THEN 'VENCIDO'\n\n            ELSE 'ABERTO'\n\n        END AS statusAtual\n\n    FROM ContaReceber cr\n\n    LEFT JOIN Cliente c ON c.idCliente = cr.cliente_id\n\n    WHERE cr.idEmpresa = p_idEmpresa\n\n      AND cr.fAtivo = 1\n\n    ORDER BY cr.dthVencimento ASC;\n\nEND	utf8mb4	utf8mb4_0900_ai_ci	utf8mb4_0900_ai_ci
